import type { SVGProps } from "react";
import styles from "./landing.module.css";

type ArtProps = SVGProps<SVGSVGElement>;

/*
 * The art is line work: ink outlines over paper shapes, with an accent and a
 * few ruled lines. Each role is a semantic token so the drawing answers to the
 * reader's light or dark choice, the same way the rest of the page does.
 *
 * INK is `currentColor` rather than a token so the outlines follow whatever
 * foreground the band sets, and PAPER is the page surface so the filled shapes
 * read as cut from the background rather than as white boxes on a dark page.
 * Inverting together is what keeps the drawing legible in either mode.
 */
const ACCENT = "var(--color-action-primary)";
const INK = "currentColor";
const PAPER = "var(--color-surface-base)";
const RULE = "var(--color-border-default)";

export function BrandMark(props: ArtProps) {
  return (
    <svg
      aria-hidden="true"
      className={styles.brandMark}
      viewBox="0 0 24 24"
      {...props}
    >
      <rect height="18" rx="5" width="18" x="3" y="3" />
      <path d="M8 16V9.5L12 14l4-4.5V16" />
    </svg>
  );
}

